1034	
1035	// ─── GELU (tanh approx, matches PyTorch nn.GELU default) ───────────────
1036	// gelu(x) = 0.5 * x * (1 + tanh( sqrt(2/pi) * (x + 0.044715 * x^3) ))
1037	// Backward: dx = dy * d/dx gelu(x)
1038	
1039	template <typename ActT>
1040	__global__ void gelu_fwd_kernel(const ActT* in, ActT* out, size_t n) {
1041	    size_t i = (size_t)blockIdx.x * blockDim.x + threadIdx.x;
1042	    if (i >= n) return;
1043	    float x = to_f32(in[i]);
1044	    const float k = 0.7978845608f;  // sqrt(2/pi)
1045	    float t = k * (x + 0.044715f * x * x * x);
1046	    out[i] = from_f32<ActT>(0.5f * x * (1.0f + tanhf(t)));
1047	}
1048	
1049	template <typename ActT>
1050	__global__ void gelu_bwd_kernel(const ActT* in, const ActT* dy, ActT* dx, size_t n) {
1051	    size_t i = (size_t)blockIdx.x * blockDim.x + threadIdx.x;
1052	    if (i >= n) return;
1053	    float x = to_f32(in[i]);
1054	    const float k = 0.7978845608f;
1055	    float u = k * (x + 0.044715f * x * x * x);
1056	    float th = tanhf(u);
1057	    float dudx = k * (1.0f + 3.0f * 0.044715f * x * x);
1058	    float dgelu = 0.5f * (1.0f + th) + 0.5f * x * (1.0f - th * th) * dudx;
1059	    dx[i] = from_f32<ActT>(to_f32(dy[i]) * dgelu);
1060	}
1061	
1062	template <typename ActT>
1063	inline cudaError_t launch_gelu_fwd(const ActT* in, ActT* out, size_t n, cudaStream_t stream) {
1064	    int block = 256; int grid = (int)((n + block - 1) / block);
1065	    gelu_fwd_kernel<ActT><<<grid, block, 0, stream>>>(in, out, n);
1066	    return cudaGetLastError();
1067	}
1068	
1069	template <typename ActT>
1070	inline cudaError_t launch_gelu_bwd(const ActT* in, const ActT* dy, ActT* dx, size_t n, cudaStream_t stream) {
1071	    int block = 256; int grid = (int)((n + block - 1) / block);
1072	    gelu_bwd_kernel<ActT><<<grid, block, 0, stream>>>(in, dy, dx, n);
1073	    return cudaGetLastError();
1074	}
1075	
1076	// ─── CLS extract: read x[:, 0, :] -> y[:, :] ────────────────────────────
1077	template <typename ActT>
1078	__global__ void cls_extract_fwd_kernel(
1079	    const ActT* __restrict__ tokens,    // [B, S, D]
1080	    ActT* __restrict__ cls,             // [B, D]
1081	    int batch, int seq, int d_model
1082	) {
1083	    int b = blockIdx.x;
1084	    if (b >= batch) return;
1085	    for (int d = threadIdx.x; d < d_model; d += blockDim.x) {
1086	        cls[(size_t)b * d_model + d] = tokens[((size_t)b * seq + 0) * d_model + d];
1087	    }
1088	}
1089	
1090	template <typename ActT>
1091	__global__ void cls_scatter_bwd_kernel(
1092	    const ActT* __restrict__ d_cls,     // [B, D]
1093	    ActT* __restrict__ d_tokens,        // [B, S, D]   (zeroed for s != 0)
1094	    int batch, int seq, int d_model
1095	) {
1096	    int b = blockIdx.x;
1097	    int s = blockIdx.y;
1098	    if (b >= batch || s >= seq) return;
1099	    for (int d = threadIdx.x; d < d_model; d += blockDim.x) {
1100	        if (s == 0) {
1101	            d_tokens[((size_t)b * seq + 0) * d_model + d] = d_cls[(size_t)b * d_model + d];
1102	        } else {
1103	            d_tokens[((size_t)b * seq + s) * d_model + d] = from_f32<ActT>(0.0f);
1104	        }
1105	    }
1106	}
1107	
1108	// ════════════════════════════════════════════════════════════════════════
1109	// Forward pass
1110	// ════════════════════════════════════════════════════════════════════════
1111	template <typename ActT, typename WeightT>
1112	cudaError_t forward(
1113	    const ActT* input,
1114	    const WeightT* weights,
1115	    ActT* output,
1116	    ActT* activations,
1117	    int batch, int channels, int height, int width,
1118	    int patch_size, int d_model, int n_heads, int d_head,
1119	    int n_layers, int n_classes, int ffn_expansion,
1120	    cudaStream_t stream
1121	) {
1122	    if (patch_size <= 0 || height % patch_size != 0 || width % patch_size != 0) {
1123	        return cudaErrorInvalidValue;
1124	    }
1125	    int num_patches = (height / patch_size) * (width / patch_size);
1126	    int patch_dim   = patch_size * patch_size * channels;
1127	    int seq_len     = num_patches + 1;
1128	    int ffn_hidden  = (int)(ffn_expansion * d_model);
1129	    int HD          = n_heads * d_head;
1130	
1131	    WeightLayout<WeightT> w{};
1132	    w.base = weights; w.d_model = d_model; w.n_heads = n_heads; w.d_head = d_head;
1133	    w.ffn_hidden = ffn_hidden; w.n_layers = n_layers; w.n_classes = n_classes;
1134	    w.num_patches = num_patches; w.patch_dim = patch_dim; w.seq_len = seq_len;
1135	
1136	    ActLayout<ActT> A{};
1137	    A.base = activations; A.batch = batch; A.seq_len = seq_len; A.d_model = d_model;
1138	    A.n_heads = n_heads; A.d_head = d_head; A.ffn_hidden = ffn_hidden;
1139	    A.n_layers = n_layers; A.n_classes = n_classes;
1140	
1141	    cudaError_t err;
1142	
1143	    // Step 1: patch projection — input is [B, num_patches, patch_dim] flat.
1144	    //   patches_proj = input @ patch_W^T + patch_b
1145	    // We project directly into the layer-0 "pre_attn_in" buffer's "patches"
1146	    // region by routing through a temporary ActT scratch (layer-0 attn_out).
1147	    auto L0 = A.layer(0);
1148	    ActT* patches_proj = L0.proj_out;  // reuse: temporary scratch (overwritten before use)
1149	#ifdef WITH_CUTLASS
1150	    err = launch_linear_bias<ActT, WeightT>(
1151	        input, w.patch_W(), w.patch_b(), patches_proj,
1152	        /*M=*/batch * num_patches, /*N=*/d_model, /*K=*/patch_dim, stream);
1153	#else
1154	    err = launch_gemm_bias<ActT, WeightT>(
1155	        input, w.patch_W(), w.patch_b(), patches_proj,
1156	        /*M=*/batch * num_patches, /*N=*/d_model, /*K=*/patch_dim, stream);
1157	#endif
1158	    if (err != cudaSuccess) return err;
1159	
1160	    // Step 2: prepend CLS + add pos embed -> tokens (= layer-0 pre_attn_in)
1161	    {
1162	        dim3 grid(seq_len, batch);
1163	        int block = 128; if (block > d_model) block = d_model;
1164	        cls_pos_fwd_kernel<ActT, WeightT><<<grid, block, 0, stream>>>(
1165	            patches_proj, w.cls_token(), w.pos_embed(),
1166	            L0.pre_attn_in, batch, num_patches, seq_len, d_model);
1167	    }
1168	    err = cudaGetLastError(); if (err != cudaSuccess) return err;
1169	
1170	    // Step 3: encoder layers
1171	    int M = batch * seq_len;
1172	    for (int L = 0; L < n_layers; L++) {
1173	        auto P = A.layer(L);
1174	
1175	        // QKV projection: [M, D] -> [M, 3*HD]
1176	#ifdef WITH_CUTLASS
1177	        err = launch_linear_bias<ActT, WeightT>(
1178	            P.pre_attn_in, w.qkv_W(L), w.qkv_b(L), P.qkv,
1179	            M, 3 * HD, d_model, stream);
1180	#else
1181	        err = launch_gemm_bias<ActT, WeightT>(
1182	            P.pre_attn_in, w.qkv_W(L), w.qkv_b(L), P.qkv,
1183	            M, 3 * HD, d_model, stream);
1184	#endif
1185	        if (err != cudaSuccess) return err;
1186	
1187	        // Split into Q/K/V [B, H, S, Dh] each via temporary scratch.
1188	        // We reuse "ffn_h_pre" as scratch for q,k,v concatenated.
1189	        // Each occupies B*H*S*Dh = bsd() (since H*Dh=d_model in default).
1190	        // To be safe even when H*Dh != d_model, we require ffn_hidden >= 3*HD.
1191	        // Otherwise we allocate via the attn_out + ln1_in + ln1_out triple.
1192	        // For simplicity here, use proj_out (size B*S*D) for each of q,k,v
1193	        // when H*Dh <= d_model.
1194	        ActT* q_buf = P.proj_out;          // size B*S*D
1195	        ActT* k_buf = P.ln1_in;            // size B*S*D
1196	        ActT* v_buf = P.ln1_out;           // size B*S*D
1197	        // These are reused before they're needed for their final purpose
1198	        // (proj_out, ln1_in, ln1_out get rewritten later in this iteration).
1199	        {
1200	            dim3 grid(seq_len, batch);
1201	            int block = 128;
1202	            split_qkv_kernel<ActT><<<grid, block, 0, stream>>>(
1203	                P.qkv, q_buf, k_buf, v_buf, batch, seq_len, n_heads, d_head);
1204	        }
1205	        err = cudaGetLastError(); if (err != cudaSuccess) return err;
1206	
1207	        // Attention: out is [B, H, S, Dh], stored into attn_out_bhsd scratch.
1208	        ActT* attn_bhsd = P.ffn_h_pre;     // size B*S*F; we need B*H*S*Dh = B*S*HD
1209	                                            // F = ffn_hidden >= d_model typically; ok if HD<=F.
1210	        float scale = 1.0f / sqrtf((float)d_head);
1211	        err = attention::attention_forward<ActT, /*kHeadDim*/32, /*kCausal*/false>(
1212	            q_buf, k_buf, v_buf, attn_bhsd,
1213	            reinterpret_cast<ActT*>(P.softmax_lse),
1214	            batch, n_heads, seq_len, scale, stream);
1215	        if (err != cudaSuccess) return err;
1216	
1217	        // Merge heads back to [B, S, H*Dh] into attn_out
1218	        {
1219	            dim3 grid(seq_len, batch);
1220	            int block = 128;
1221	            merge_attn_out_kernel<ActT><<<grid, block, 0, stream>>>(
1222	                attn_bhsd, P.attn_out, batch, seq_len, n_heads, d_head);
1223	        }
1224	        err = cudaGetLastError(); if (err != cudaSuccess) return err;
1225	
1226	        // Output projection: attn_out [M, HD] -> proj_out [M, D]
1227	#ifdef WITH_CUTLASS
1228	        err = launch_linear_bias<ActT, WeightT>(
1229	            P.attn_out, w.out_W(L), w.out_b(L), P.proj_out,
1230	            M, d_model, HD, stream);
1231	#else
1232	        err = launch_gemm_bias<ActT, WeightT>(
1233	            P.attn_out, w.out_W(L), w.out_b(L), P.proj_out,
1234	            M, d_model, HD, stream);
1235	#endif
1236	        if (err != cudaSuccess) return err;
1237	
1238	        // Residual: ln1_in = pre_attn_in + proj_out
1239	        err = launch_add<ActT>(P.pre_attn_in, P.proj_out, P.ln1_in, (size_t)M * d_model, stream);
1240	        if (err != cudaSuccess) return err;
1241	
1242	        // LayerNorm 1: ln1_out = LN(ln1_in)
1243	        err = launch_layernorm_fwd<ActT, WeightT>(
1244	            P.ln1_in, w.ln1_gamma(L), w.ln1_beta(L),
1245	            P.ln1_out, P.ln1_mean, P.ln1_invstd,
1246	            M, d_model, 1e-5f, stream);
1247	        if (err != cudaSuccess) return err;
1248	
1249	        // FFN up: ffn_h_pre = ff1_W @ ln1_out + ff1_b
1250	#ifdef WITH_CUTLASS
1251	        err = launch_linear_bias<ActT, WeightT>(
1252	            P.ln1_out, w.ff1_W(L), w.ff1_b(L), P.ffn_h_pre,
1253	            M, ffn_hidden, d_model, stream);
1254	#else
1255	        err = launch_gemm_bias<ActT, WeightT>(
1256	            P.ln1_out, w.ff1_W(L), w.ff1_b(L), P.ffn_h_pre,
1257	            M, ffn_hidden, d_model, stream);
1258	#endif
1259	        if (err != cudaSuccess) return err;
1260	
1261	        // GELU
1262	        err = launch_gelu_fwd<ActT>(P.ffn_h_pre, P.ffn_h, (size_t)M * ffn_hidden, stream);
1263	        if (err != cudaSuccess) return err;
1264	
1265	        // FFN down: ffn_out = ff2_W @ ffn_h + ff2_b
1266	#ifdef WITH_CUTLASS
1267	        err = launch_linear_bias<ActT, WeightT>(
1268	            P.ffn_h, w.ff2_W(L), w.ff2_b(L), P.ffn_out,
1269	            M, d_model, ffn_hidden, stream);
1270	#else
1271	        err = launch_gemm_bias<ActT, WeightT>(
1272	            P.ffn_h, w.ff2_W(L), w.ff2_b(L), P.ffn_out,
1273	            M, d_model, ffn_hidden, stream);
1274	#endif
1275	        if (err != cudaSuccess) return err;
1276	
1277	        // Residual: ln2_in = ln1_out + ffn_out
1278	        err = launch_add<ActT>(P.ln1_out, P.ffn_out, P.ln2_in, (size_t)M * d_model, stream);
1279	        if (err != cudaSuccess) return err;
1280	
1281	        // LayerNorm 2: ln2_out = LN(ln2_in)
1282	        err = launch_layernorm_fwd<ActT, WeightT>(
1283	            P.ln2_in, w.ln2_gamma(L), w.ln2_beta(L),
1284	            P.ln2_out, P.ln2_mean, P.ln2_invstd,
1285	            M, d_model, 1e-5f, stream);
1286	        if (err != cudaSuccess) return err;
1287	
1288	        // Plumb to next layer's pre_attn_in
1289	        if (L + 1 < n_layers) {
1290	            auto Pn = A.layer(L + 1);
1291	            cudaMemcpyAsync(Pn.pre_attn_in, P.ln2_out,
1292	                            sizeof(ActT) * (size_t)M * d_model,
1293	                            cudaMemcpyDeviceToDevice, stream);
1294	        }
1295	    }
1296	
1297	    // Step 4: extract CLS (last layer ln2_out[:, 0, :])
1298	    auto F = A.final_ptrs();
1299	    ActT* last_ln2_out = A.layer(n_layers - 1).ln2_out;
1300	    {
1301	        int block = 128; if (block > d_model) block = d_model;
1302	        cls_extract_fwd_kernel<ActT><<<batch, block, 0, stream>>>(
1303	            last_ln2_out, F.final_in, batch, seq_len, d_model);
1304	    }
1305	    err = cudaGetLastError(); if (err != cudaSuccess) return err;
1306	
1307	    // Step 5: final LayerNorm: final_out = LN(final_in)
1308	    err = launch_layernorm_fwd<ActT, WeightT>(
1309	        F.final_in, w.ln_final_gamma(), w.ln_final_beta(),
1310	        F.final_out, F.final_mean, F.final_invstd,
1311	        batch, d_model, 1e-5f, stream);
1312	    if (err != cudaSuccess) return err;
1313	
1314	    // Step 6: classification head: output = head_W @ final_out + head_b
1315	#ifdef WITH_CUTLASS
1316	    err = launch_linear_bias<ActT, WeightT>(
1317	        F.final_out, w.head_W(), w.head_b(), output,
1318	        batch, n_classes, d_model, stream);
1319	#else
1320	    err = launch_gemm_bias<ActT, WeightT>(
1321	        F.final_out, w.head_W(), w.head_b(), output,
1322	        batch, n_classes, d_model, stream);
1323	#endif
1324	    return err;
1325	}
1326	
1327	// ════════════════════════════════════════════════════════════════════════
1328	// Backward pass
1329	// ════════════════════════════════════════════════════════════════════════
1330	template <typename ActT, typename WeightT>
1331	cudaError_t backward(
1332	    const ActT* grad_output,         // [B, n_classes]
1333	    const ActT* activations_saved,
1334	    const WeightT* weights,
1335	    ActT* grad_input,                // [B, num_patches, patch_dim] (or whatever input was)
1336	    WeightT* grad_weights,
1337	    int batch, int channels, int height, int width,
1338	    int patch_size, int d_model, int n_heads, int d_head,
1339	    int n_layers, int n_classes, int ffn_expansion,
1340	    cudaStream_t stream
1341	) {
1342	    if (patch_size <= 0 || height % patch_size != 0 || width % patch_size != 0) {
1343	        return cudaErrorInvalidValue;
1344	    }
1345	    int num_patches = (height / patch_size) * (width / patch_size);
1346	    int patch_dim   = patch_size * patch_size * channels;
1347	    int seq_len     = num_patches + 1;
1348	    int ffn_hidden  = (int)(ffn_expansion * d_model);
1349	    int HD          = n_heads * d_head;
1350	    int M           = batch * seq_len;
1351	
1352	    WeightLayout<WeightT> w{};
1353	    w.base = weights; w.d_model = d_model; w.n_heads = n_heads; w.d_head = d_head;
1354	    w.ffn_hidden = ffn_hidden; w.n_layers = n_layers; w.n_classes = n_classes;
1355	    w.num_patches = num_patches; w.patch_dim = patch_dim; w.seq_len = seq_len;
1356	
1357	    WeightLayout<WeightT> dw{};
1358	    dw.base = grad_weights; dw.d_model = d_model; dw.n_heads = n_heads; dw.d_head = d_head;
1359	    dw.ffn_hidden = ffn_hidden; dw.n_layers = n_layers; dw.n_classes = n_classes;
1360	    dw.num_patches = num_patches; dw.patch_dim = patch_dim; dw.seq_len = seq_len;
1361	
1362	    ActLayout<ActT> A{};
1363	    A.base = const_cast<ActT*>(activations_saved); A.batch = batch; A.seq_len = seq_len;
1364	    A.d_model = d_model; A.n_heads = n_heads; A.d_head = d_head; A.ffn_hidden = ffn_hidden;
1365	    A.n_layers = n_layers; A.n_classes = n_classes;
1366	
1367	    auto F = A.final_ptrs();
1368	
1369	    // Allocate scratch for backward: grad arrays of various sizes. We
1370	    // request them from a single device-side scratch via cudaMallocAsync.
1371	    // Size budget (worst case):
1372	    //   d_tokens  : B * S * D
1373	    //   d_residual: B * S * D
1374	    //   d_attn_out: B * S * HD
1375	    //   d_attn_bhsd: B * H * S * Dh
1376	    //   d_q,d_k,d_v: 3 * B * H * S * Dh
1377	    //   d_ffn_h    : B * S * F
1378	    //   d_cls      : B * D
1379	    //   d_final_in : B * D
1380	    // Total ~ B*S*(D + D + HD + ffn_hidden) + B*D.
1381	    size_t bsd  = (size_t)batch * seq_len * d_model;
1382	    size_t bsh  = (size_t)batch * seq_len * 3 * HD;
1383	    size_t bsf  = (size_t)batch * seq_len * ffn_hidden;
1384	    size_t bhsd = (size_t)batch * n_heads * seq_len * d_head;
1385	    size_t bd   = (size_t)batch * d_model;
1386	
1387	    size_t scratch_n = bsd*4 + bsh + bsf + bhsd*3 + bd*2;
1388	    ActT* scratch = nullptr;
1389	    cudaError_t err = cudaMallocAsync((void**)&scratch, scratch_n * sizeof(ActT), stream);
1390	    if (err != cudaSuccess) return err;
1391	
1392	    ActT* d_final_in = scratch;                            // [B, D]
1393	    ActT* d_cls      = d_final_in  + bd;                   // [B, D]
1394	    ActT* d_tokens   = d_cls       + bd;                   // [B, S, D]
1395	    ActT* d_resid    = d_tokens    + bsd;                  // [B, S, D]
1396	    ActT* d_attn_o   = d_resid     + bsd;                  // [B, S, HD] — bsd slots (HD<=D ok)
1397	    ActT* d_attn_bhsd= d_attn_o    + bsd;                  // [B, H, S, Dh]
1398	    ActT* d_q        = d_attn_bhsd + bhsd;                 // [B, H, S, Dh]
1399	    ActT* d_k        = d_q         + bhsd;                 // [B, H, S, Dh]
1400	    ActT* d_v        = d_k         + bhsd;                 // [B, H, S, Dh]
1401	    ActT* d_ffn_h    = d_v         + bhsd;                 // [B, S, F]
1402	    // d_q,d_k,d_v contiguous (3*bhsd = bsh) doubles as merged d_qkv buffer.
1403	    (void)bsh;
1404	
1405	    // Body returns cudaError_t; cleanup happens after the lambda.
1406	    auto body = [&]() -> cudaError_t {
1407	
1408	    // Step 1: head_W backward
1409	    //   grad_final_out = grad_output @ head_W
1410	    //   d_head_W = grad_output^T @ final_out
1411	    //   d_head_b = sum_b grad_output
1412	    err = launch_gemm_grad_input<ActT, WeightT>(
1413	        grad_output, w.head_W(), d_final_in, batch, n_classes, d_model, stream);
1414	    if (err != cudaSuccess) return err;
1415	    err = launch_gemm_grad_weight<ActT, WeightT>(
1416	        grad_output, F.final_out,
1417	        const_cast<WeightT*>(dw.head_W()), const_cast<WeightT*>(dw.head_b()),
1418	        batch, n_classes, d_model, stream);
1419	    if (err != cudaSuccess) return err;
1420	
1421	    // Step 2: final LN backward
1422	    //   d_cls = LN_bwd(d_final_in)
1423	    //   d_ln_final_gamma, d_ln_final_beta accumulate
1424	    err = launch_layernorm_bwd<ActT, WeightT>(
1425	        F.final_in, d_final_in, w.ln_final_gamma(),
1426	        F.final_mean, F.final_invstd,
1427	        d_cls, batch, d_model, stream);
1428	    if (err != cudaSuccess) return err;
1429	    err = launch_layernorm_grad_param<ActT, WeightT>(
1430	        F.final_in, d_final_in, F.final_mean, F.final_invstd,
1431	        const_cast<WeightT*>(dw.ln_final_gamma()),
1432	        const_cast<WeightT*>(dw.ln_final_beta()),
1433	        batch, d_model, stream);
