939	    const WeightT* __restrict__ gamma,    // [D]

935	template <typename ActT, typename WeightT>
936	__global__ void layernorm_bwd_kernel(
937	    const ActT* __restrict__ x,           // [M, D] (input to LN)
938	    const ActT* __restrict__ dy,          // [M, D]
939	    const WeightT* __restrict__ gamma,    // [D]
940	    const float* __restrict__ mean,       // [M]
941	    const float* __restrict__ invstd,     // [M]
942	    ActT* __restrict__ dx,                // [M, D]
943	    int M, int D
944	) {
945	    int m = blockIdx.x;
946	    if (m >= M) return;
947	    int tid = threadIdx.x;
948	    float mu = mean[m];
949	    float inv = invstd[m];
950	
951	    extern __shared__ float smem[];
952	    float sum_a = 0.0f;  // sum(dy * gamma)
953	    float sum_b = 0.0f;  // sum(dy * gamma * x_hat)
954	    for (int d = tid; d < D; d += blockDim.x) {
955	        float dyv = to_f32(dy[(size_t)m * D + d]);
956	        float g = to_f32(gamma[d]);
957	        float xh = (to_f32(x[(size_t)m * D + d]) - mu) * inv;
958	        sum_a += dyv * g;
959	        sum_b += dyv * g * xh;
960	    }
961	    smem[tid] = sum_a; __syncthreads();
962	    for (int off = blockDim.x / 2; off > 0; off >>= 1) {
963	        if (tid < off) smem[tid] += smem[tid + off];
964	        __syncthreads();
965	    }
966	    float sa = smem[0]; __syncthreads();
967	    smem[tid] = sum_b; __syncthreads();
968	    for (int off = blockDim.x / 2; off > 0; off >>= 1) {
969	        if (tid < off) smem[tid] += smem[tid + off];
970	        __syncthreads();
971	    }
972	    float sb = smem[0]; __syncthreads();
973	
974	    float invD = 1.0f / (float)D;
975	    for (int d = tid; d < D; d += blockDim.x) {
976	        float dyv = to_f32(dy[(size_t)m * D + d]);
977	        float g = to_f32(gamma[d]);
978	        float xh = (to_f32(x[(size_t)m * D + d]) - mu) * inv;
979	        float dxv = inv * (dyv * g - invD * sa - xh * invD * sb);
980	        dx[(size_t)m * D + d] = from_f32<ActT>(dxv);
981	    }
982	}
