1038	
1039	template <typename ActT>
1040	__global__ void gelu_fwd_kernel(const ActT* in, ActT* out, size_t n) {
1041	    size_t i = (size_t)blockIdx.x * blockDim.x + threadIdx.x;
1042	    if (i >= n) return;
1043	    float x = to_f32(in[i]);
1044	    const float k = 0.7978845608f;  // sqrt(2/pi)
1045	    float t = k * (x + 0.044715f * x * x * x);
1046	    out[i] = from_f32<ActT>(0.5f * x * (1.0f + tanhf(t)));
1047	}
1048	
1049	template <typename ActT>
1050	__global__ void gelu_bwd_kernel(const ActT* in, const ActT* dy, ActT* dx, size_t n) {
1051	    size_t i = (size_t)blockIdx.x * blockDim.x + threadIdx.x;
1052	    if (i >= n) return;
1053	    float x = to_f32(in[i]);
1054	    const float k = 0.7978845608f;
1055	    float u = k * (x + 0.044715f * x * x * x);
1056	    float th = tanhf(u);
1057	    float dudx = k * (1.0f + 3.0f * 0.044715f * x * x);
1058	    float dgelu = 0.5f * (1.0f + th) + 0.5f * x * (1.0f - th * th) * dudx;
1059	    dx[i] = from_f32<ActT>(to_f32(dy[i]) * dgelu);
1060	}
